import sys,os,json,base64,tempfile,webbrowser,threading,time,traceback
from PySide6.QtWidgets import QApplication,QMainWindow,QFileDialog,QWidget
from PySide6.QtWebEngineWidgets import QWebEngineView
from PySide6.QtWebEngineCore import QWebEngineProfile,QWebEnginePage,QWebEngineSettings
from PySide6.QtCore import QUrl,Qt,QObject,Signal,QTimer
from PySide6.QtGui import QIcon,QPixmap

NAME="menemeow";TITLE="Button Clicker";W=800;H=500;FULL=False;TOP=False;BASLA=False;ICON=""
HTML=base64.b64decode("").decode("utf-8")
if BASLA:
    try:
        import winreg
        k=winreg.OpenKey(winreg.HKEY_CURRENT_USER,r"Software\Microsoft\Windows\CurrentVersion\Run",0,winreg.KEY_SET_VALUE)
        winreg.SetValueEx(k,NAME,0,winreg.REG_SZ,'"'+sys.executable+'"')
    except Exception: pass
app=QApplication(sys.argv)
class Br(QObject):
    js=Signal(str)
br=Br()
base=os.path.join(os.environ.get("APPDATA",tempfile.gettempdir()),"UGCO_"+NAME)
os.makedirs(base,exist_ok=True)
with open(os.path.join(base,"index.html"),"w",encoding="utf-8") as f: f.write(HTML)
PICS=os.path.join(os.path.expanduser("~"),"Pictures",NAME)
os.makedirs(PICS,exist_ok=True)
prof=QWebEngineProfile("ugco_"+NAME)
prof.setPersistentStoragePath(os.path.join(base,"data")); prof.setCachePath(os.path.join(base,"cache"))
def indir(d):
    d.setDownloadDirectory(PICS); d.accept()
prof.downloadRequested.connect(indir)
BUF={}
class Page(QWebEnginePage):
    def javaScriptConsoleMessage(s,lvl,msg,line,src):
        if msg.startswith("\x01UGCO\x02"):
            try:
                _,c,i,k,n,p=msg.split("\x02",5); k=int(k); n=int(n)
                b=BUF.setdefault(i,{}); b[k]=p
                if len(b)==n:
                    del BUF[i]; tam="".join(b[x] for x in range(n))
                    QTimer.singleShot(0,lambda:ISLE(c,tam))
            except Exception: pass
            return
        super().javaScriptConsoleMessage(lvl,msg,line,src)
    def __init__(s,p,parent=None):
        super().__init__(p,parent)
        try: s.permissionRequested.connect(lambda q:q.grant())
        except Exception: s.featurePermissionRequested.connect(lambda u,f:s.setFeaturePermission(u,f,QWebEnginePage.PermissionPolicy.PermissionGrantedByUser))
    def createWindow(s,t):
        pg2=QWebEnginePage(s)
        pg2.urlChanged.connect(lambda u:webbrowser.open(u.toString()))
        return pg2
w=QMainWindow(); w.setWindowTitle(TITLE); w.resize(W,H)
px=QPixmap(); px.loadFromData(base64.b64decode(ICON)); w.setWindowIcon(QIcon(px))
if TOP: w.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint,True)
WEBS={}
def yerlestir(o):
    l,t,wd,ht=o.frac; a,b=cen.width(),cen.height()
    o.setGeometry(int(l*a),int(t*b),int(wd*a),int(ht*b))
class Cen(QWidget):
    def resizeEvent(s,e):
        super().resizeEvent(e)
        v.setGeometry(0,0,s.width(),s.height())
        for o in WEBS.values(): yerlestir(o)
class WPage(Page):
    def createWindow(s,t):
        pg3=QWebEnginePage(s)
        pg3.urlChanged.connect(lambda u:s.setUrl(u))
        return pg3
cen=Cen(); v=QWebEngineView(cen); pg=Page(prof,v); v.setPage(pg); w.setCentralWidget(cen)
ayar=pg.settings()
ayar.setAttribute(QWebEngineSettings.WebAttribute.LocalContentCanAccessRemoteUrls,True)
ayar.setAttribute(QWebEngineSettings.WebAttribute.PlaybackRequiresUserGesture,False)
br.js.connect(lambda c:pg.runJavaScript(c))

def DOSYA(a):
    tur,_,co=a.partition("|")
    F={"resim":"Resimler (*.png *.jpg *.jpeg *.gif *.bmp *.webp)","ses":"Ses (*.mp3 *.wav *.ogg *.m4a *.flac)","video":"Video (*.mp4 *.webm *.mkv *.avi *.mov)"}
    f=F.get(tur,"Medya (*.png *.jpg *.jpeg *.gif *.bmp *.webp *.mp3 *.wav *.ogg *.m4a *.flac *.mp4 *.webm *.mkv *.avi *.mov);;Tüm dosyalar (*.*)")
    if co=="1": l=QFileDialog.getOpenFileNames(w,"Dosya seç",os.path.expanduser("~"),f)[0]
    else:
        x=QFileDialog.getOpenFileName(w,"Dosya seç",os.path.expanduser("~"),f)[0]
        l=[x] if x else []
    pg.runJavaScript("window.ugcoDosya(%s)"%json.dumps([QUrl.fromLocalFile(p).toString() for p in l]))
def METINOKU():
    x=QFileDialog.getOpenFileName(w,"Dosya aç",os.path.expanduser("~"),"Metin dosyaları (*.txt *.csv *.json *.md *.log *.ini);;Tüm dosyalar (*.*)")[0]
    if not x: return
    try: t=open(x,encoding="utf-8").read()
    except UnicodeDecodeError: t=open(x,encoding="cp1254",errors="replace").read()
    pg.runJavaScript("window.ugcoMetin(%s,%s)"%(json.dumps(t),json.dumps(os.path.basename(x))))
def METINYAZ(a):
    ad,t=json.loads(a)
    x=QFileDialog.getSaveFileName(w,"Kaydet",os.path.join(os.path.expanduser("~"),ad or "dosya.txt"),"Metin dosyası (*.txt);;Tüm dosyalar (*.*)")[0]
    if not x: return
    with open(x,"w",encoding="utf-8") as f: f.write(t)
    pg.runJavaScript("window.ugcoKaydedildi(%s)"%json.dumps(x))
def RESIMKAYDET(a):
    ad,d=json.loads(a)
    b=d.partition(",")[2]
    yol=os.path.join(PICS,"".join(ch for ch in ad if ch.isalnum() or ch in "-_")+".jpg")
    with open(yol,"wb") as f: f.write(base64.b64decode(b))
    pg.runJavaScript("UGCO.uyari(%s)"%json.dumps("Fotoğraf kaydedildi: "+yol))
def LOG(m):
    try:
        with open(os.path.join(base,"hata.txt"),"a",encoding="utf-8") as f: f.write(time.strftime("%H:%M:%S ")+m+"\n")
    except Exception: pass
def adres(u):
    u=u.strip()
    return u if "://" in u else "https://"+u
def web_isle(k,a):
    d=json.loads(a)
    if k=="WEBEKLE":
        o=WEBS.get(d[0])
        if o is None:
            o=QWebEngineView(cen); o.setPage(WPage(prof,o)); WEBS[d[0]]=o; o.load(QUrl(adres(d[1])))
        o.frac=(d[2],d[3],d[4],d[5]); yerlestir(o); o.show(); o.raise_()
    elif k=="WEBGIT" and d[0] in WEBS: WEBS[d[0]].load(QUrl(adres(d[1])))
    elif k=="WEBGOR" and d[0] in WEBS: WEBS[d[0]].setVisible(bool(d[1]))
def isle(k,a):
    if k=="KAPAT": w.close()
    elif k=="LINK": webbrowser.open(a)
    elif k=="PANO": QApplication.clipboard().setText(a)
    elif k=="DOSYA": DOSYA(a)
    elif k=="METINOKU": METINOKU()
    elif k=="METINYAZ": METINYAZ(a)
    elif k=="RESIMKAYDET": RESIMKAYDET(a)
    elif k.startswith("WEB"): web_isle(k,a)
    pass
def ISLE(c,p):
    try: isle(c,p)
    except Exception as ex:
        LOG(traceback.format_exc())
        pg.runJavaScript("UGCO.uyari(%s)"%json.dumps("Hata ("+c+"): "+str(ex)[:150]))
v.load(QUrl.fromLocalFile(os.path.join(base,"index.html")))
w.showFullScreen() if FULL else w.show()
sys.exit(app.exec())
